param([switch]$TrustedLocal)
$ErrorActionPreference='Stop';$logs='C:\logs\verifier';$root='C:\bench-fixtures\job';$exe='C:\testbed\bin\WinTask.exe';New-Item -ItemType Directory -Force $logs|Out-Null;Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue;& 'C:\testbed\build.ps1' *> (Join-Path $logs 'candidate-build.log');if($LASTEXITCODE -ne 0){throw 'candidate build failed'}
$required=@('fast_child_completes','repeatable_runs','timeout_code','timeout_tree_cleanup','no_late_marker','worker_script_cleanup');$cases=@();function Assert([bool]$ok,[string]$m){if(-not $ok){throw $m}};function Reset{Remove-Item $root -Recurse -Force -ErrorAction SilentlyContinue;New-Item -ItemType Directory -Force $root|Out-Null};function Invoke-App([string[]]$a){$global:LASTEXITCODE=0;$t=(& $exe @a 2>&1|Out-String).Trim();[pscustomobject]@{Code=[int]$LASTEXITCODE;Text=$t}};function Case([string]$id,[string]$g,[scriptblock]$b){$sw=[Diagnostics.Stopwatch]::StartNew();try{&$b;$s='PASS';$m=$null}catch{$s='FAIL';$m=$_.Exception.Message};$sw.Stop();$script:cases+=[pscustomobject]@{id=$id;group=$g;status=$s;message=$m;duration_ms=$sw.Elapsed.TotalMilliseconds}}
Case 'fast_child_completes' 'P2P' {Reset;$m=Join-Path $root 'fast.txt';$r=Invoke-App @($m,'100','15000');Assert($r.Code -eq 0)$r.Text;Start-Sleep -Milliseconds 150;Assert(Test-Path $m)'fast marker missing';Remove-Item $m -Force -ErrorAction SilentlyContinue}
Case 'repeatable_runs' 'P2P' {Reset;foreach($n in 1..2){$m=Join-Path $root ("r$n.txt");$r=Invoke-App @($m,'80','15000');Assert($r.Code -eq 0)$r.Text;Assert((Test-Path $m))'repeat marker missing';Remove-Item $m -Force}}
Case 'timeout_code' 'P2P' {Reset;$m=Join-Path $root 'timeout.txt';$r=Invoke-App @($m,'900','100');Assert($r.Code -eq 124)'wrong timeout code';}
Case 'timeout_tree_cleanup' 'F2P' {Reset;$m=Join-Path $root 'tree.txt';$r=Invoke-App @($m,'700','100');Assert($r.Code -eq 124)'timeout not reported';Start-Sleep -Milliseconds 1000;Assert(-not(Test-Path $m))'descendant survived'}
Case 'no_late_marker' 'F2P' {Reset;$m=Join-Path $root 'late.txt';$r=Invoke-App @($m,'500','80');Assert($r.Code -eq 124)'timeout not reported';Start-Sleep -Milliseconds 900;Assert(-not(Test-Path $m))'late write observed'}
Case 'worker_script_cleanup' 'F2P' {Reset;$m=Join-Path $root 'script.txt';$r=Invoke-App @($m,'600','80');Assert($r.Code -eq 124)'timeout not reported';Start-Sleep -Milliseconds 150;Assert(-not(Test-Path ($m+'.'+('worker'+[char]46+'cmd'))))'worker script leaked'}
$score=if(@($cases|Where-Object status -ne 'PASS').Count -eq 0){1}else{0};$result=[ordered]@{validity='VALID';score=$score;required=$required;testcases=$cases};$result|ConvertTo-Json -Depth 8|Set-Content (Join-Path $logs 'results.json') -Encoding UTF8;[IO.File]::WriteAllText((Join-Path $logs 'reward.txt'),[string]$score,[Text.Encoding]::ASCII);exit 0


